mapper.select:
SELECT s.*,c.name AS category_name FROM setmeal s left OUTER JOIN category c ON s.category_id = c.id


        and s.name like concat('%',#{name},'%')


        and s.category_id = #{categoryId}


        and s.status = #{status}


order by s.create_time desc

mapper.update:
update setmeal
name = #{name}, category_id = #{categoryId}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select * from setmeal


        and name like concat('%',#{name},'%')


        and category_id = #{categoryId}


        and status = #{status}

select s.id, s.category_id, s.name, s.price, s.status, s.description, s.image, max(coalesce(d.spicy_level, 0)) as spicy_level from setmeal s left join setmeal_dish sd on sd.setmeal_id = s.id left join dish d on d.id = sd.dish_id where s.status = 1
and s.price <= #{budget}
and s.category_id = #{categoryId}
group by s.id, s.category_id, s.name, s.price, s.status, s.description, s.image
having max(coalesce(d.spicy_level, 0)) <= #{maxSpicy}
order by s.price limit 50
